//! Embedded data — every `data/owen` file compiled into the library.
//!
//! Generated by `build.rs` into `OUT_DIR/embedded_data.rs`. This is the
//! self-contained fallback that makes a bare `libOwenServer.so` serve the
//! complete backend (battle pass, profiles, responses, manifests,
//! CloudStorage INIs) with zero external files; files that exist on disk
//! under the data dir always take precedence (operator overrides).

include!(concat!(env!("OUT_DIR"), "/embedded_data.rs"));

/// Look up one embedded file by its repo-relative path
/// (e.g. `battlepass/Season12.json`, `responses/catalog.json`).
pub fn embedded_file(rel: &str) -> Option<&'static [u8]> {
    let rel = rel.trim_start_matches('/');
    EMBEDDED_DATA
        .iter()
        .find(|(name, _)| *name == rel)
        .map(|(_, data)| *data)
}

/// Every embedded path that starts with `prefix` (directory listing).
pub fn embedded_dir(prefix: &str) -> Vec<&'static str> {
    let prefix = prefix.trim_start_matches('/').trim_end_matches('/');
    EMBEDDED_DATA
        .iter()
        .filter(|(name, _)| prefix.is_empty() || name.starts_with(&format!("{prefix}/")))
        .map(|(name, _)| *name)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn core_files_are_embedded() {
        // The non-negotiables: the server must boot standalone.
        assert!(embedded_file("manifests.json").is_some(), "manifests.json");
        assert!(embedded_file("responses/catalog.json").is_some(), "catalog");
        assert!(embedded_file("responses/keychain.json").is_some(), "keychain");
        assert!(
            embedded_file("CloudStorage/DefaultEngine.ini").is_some(),
            "DefaultEngine.ini"
        );
        assert!(
            embedded_file("battlepass/Season12.json").is_some(),
            "battle pass S12"
        );
        // profiles tree
        assert!(embedded_file("profiles/athena.json").is_some(), "athena");
        // …and the embedded dir listing works
        assert!(!embedded_dir("battlepass").is_empty());
        assert!(embedded_dir("battlepass").len() >= 40);
    }
}
